BEGIN;
SELECT id FROM "Exercise" WHERE id='00000000-0000-4000-8000-000000000120' AND "ownerUserId" IS NULL AND name='Puxada Frontal' FOR UPDATE;
UPDATE "Exercise" SET "anatomyReview"='{"version":"2026-11-16.scapular.1","reviewedAt":"2026-11-16T15:00:00.000Z","variant":"Puxada frontal sentada na polia alta, barra reta e pegada pronada a cerca de 1,5 vez a largura dos ombros; tronco estável levemente reclinado.","aliases":["puxada frontal"],"participants":[{"id":"LATISSIMUS_DORSI","label":"Latíssimo do dorso","muscleGroup":"BACK","role":"PRIMARY","aliases":["dorsal","grande dorsal","latissimus dorsi"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["BUONSENSO_2025","OPENSTAX_UPPER"]},{"id":"TERES_MAJOR","label":"Redondo maior","muscleGroup":"BACK","role":"PRIMARY","aliases":["teres major"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"TRAPEZIUS","label":"Trapézio","muscleGroup":"BACK","role":"SECONDARY","aliases":["trapézio médio","trapézio inferior","trapezius"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["BUONSENSO_2025","OPENSTAX_UPPER"]},{"id":"RHOMBOIDS","label":"Romboides","muscleGroup":"BACK","role":"SECONDARY","aliases":["romboide maior","romboide menor"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"DELTOID_POSTERIOR","label":"Deltoide posterior","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["ombro posterior"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["BUONSENSO_2025","OPENSTAX_UPPER"]},{"id":"INFRASPINATUS","label":"Infraespinal","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["infraespinhoso","manguito rotador"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["BUONSENSO_2025","OPENSTAX_UPPER"]},{"id":"BICEPS_BRACHII","label":"Bíceps braquial","muscleGroup":"BICEPS","role":"SECONDARY","aliases":["bíceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["BUONSENSO_2025","OPENSTAX_UPPER"]},{"id":"BRACHIALIS","label":"Braquial","muscleGroup":"BICEPS","role":"SECONDARY","aliases":["braquial anterior"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"BRACHIORADIALIS","label":"Braquiorradial","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["braquiorradialis"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"FLEXOR_DIGITORUM_SUPERFICIALIS","label":"Flexor superficial dos dedos","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["pegada"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"FLEXOR_DIGITORUM_PROFUNDUS","label":"Flexor profundo dos dedos","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["pegada"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"FLEXOR_CARPI_ULNARIS","label":"Flexor ulnar do carpo","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["punho"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"EXTENSOR_CARPI_RADIALIS_BREVIS","label":"Extensor radial curto do carpo","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["punho"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"ERECTOR_SPINAE","label":"Eretores da coluna","muscleGroup":"BACK","role":"SECONDARY","aliases":["eretor da espinha","estabilizadores do tronco"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"RECTUS_ABDOMINIS","label":"Reto abdominal","muscleGroup":"CORE","role":"SECONDARY","aliases":["abdômen","abdominais"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"EXTERNAL_OBLIQUE","label":"Oblíquo externo","muscleGroup":"CORE","role":"SECONDARY","aliases":["oblíquos"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"SERRATUS_ANTERIOR","label":"Serrátil anterior","muscleGroup":"BACK","role":"SECONDARY","aliases":["serratus anterior","controle escapular"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OYAMA_2010"]}],"sources":[{"id":"BUONSENSO_2025","title":"Buonsenso et al. — Electromyographic Analysis of Back Muscle Activation During Lat Pulldown Exercise (2025)","url":"https://doi.org/10.3390/jfmk10030345","limitation":"40 homens com pelo menos cinco anos de treino; cinco repetições a 70% de 1RM, sete pegadas/inclinações e cadência 2 s/2 s. EMG de dorsal, trapézio médio/inferior, deltoide posterior, bíceps e infraespinal. Sem superioridade geral entre pegadas; maior sinal de deltoide posterior com 30° em comparações específicas. Não mede hipertrofia nem determina ângulos ideais."},{"id":"OPENSTAX_UPPER","title":"OpenStax Anatomy and Physiology 2e — Muscles of the Pectoral Girdle and Upper Limbs","url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/11-5-muscles-of-the-pectoral-girdle-and-upper-limbs","limitation":"Anatomia funcional: adução/extensão do ombro, flexão do cotovelo, controle escapular e pegada. Papéis não medidos no estudo e estabilização do tronco são inferências anatômicas/editoriais, sem quantificação nesta variação."},{"id":"PADOVAN_SCAPULA_2026","title":"Padovan et al. — Scapular positions in the seated row (2026; online 24/12/2025)","url":"https://doi.org/10.3390/jfmk11010006","limitation":"14 homens treinados, remada sentada, 8RM, quatro repetições; HD-sEMG por fase, sem medir a cinemática do avatar ou hipertrofia. Movimento livre e escápulas fixas são condições distintas. Extrapolação para remada em pé/unilateral é anatômica e editorial."},{"id":"OYAMA_2010","title":"Oyama et al. — Three-dimensional scapular and clavicular kinematics during retraction exercises","url":"https://doi.org/10.2519/jospt.2010.3018","limitation":"Adultos jovens saudáveis, seis exercícios de retração; rotação externa, rotação superior e inclinação posterior escapular, retração/depressão clavicular. Quantidades variam por tarefa. As amplitudes do avatar são ilustrativas, não valores medidos nesses exercícios."},{"id":"VASCONCELOS_2023","title":"Vasconcelos et al. — Grip position and shoulder-abduction angle in the seated cable row","url":"https://doi.org/10.47206/ijsc.v3i1.190","limitation":"11 homens e 10 mulheres recreacionalmente treinados; testes isométricos/dinâmicos, pegadas pronada/supinada/neutra e abdução 30/60/90°. Maior abdução favoreceu trapézio/deltoide posterior nos registros; menor abdução, dorsal. Transferência para barra livre é inferência, não medição ou isolamento."}],"notes":"Dorsal e redondo maior são os motores destacados; flexores do cotovelo, controle escapular, manguito, pegada e estabilizadores do tronco são coenvolvidos. Grupo BACK permanece principal, embora eretores/trapézio/romboides tenham papel secundário específico. Sem isolamento do dorsal, ranking de EMG ou ênfase regional demonstrada. Inclinação fixa de cerca de 7°, barra à frente do rosto e pegada de 1,5 vez os ombros são escolhas ilustrativas confortáveis do rig, não ótimos universais. Não extrapolar os resultados de 30° para esta postura. Sem subdividir dorsal em regiões não comprovadas. Cores representam categorias ilustrativas. Equivalência da execução pronada no pulley verificada no canonical-media-catalog para o UUID ...120; preservado como cadastro distinto, sem fusão de IDs. Revisão escapular: Na volta acima da cabeça, permita elevação e rotação superior das escápulas. Ao puxar, elas acompanham a descida dos braços; não as mantenha permanentemente presas para baixo. Serrátil anterior participa do controle, em destaque secundário ilustrativo. Escápulas têm controles independentes e pesos anatômicos; a trajetória não é produzida apenas pelo cotovelo. Ângulos não são medidas individuais.","instructions":{"description":"Puxada frontal na polia alta, sentada, com barra e pegada pronada moderadamente aberta.","setup":"Ajuste o assento e o apoio sobre as coxas. Apoie os pés no chão e segure a barra um pouco além dos ombros, com as palmas voltadas para a frente. Mantenha o tronco firme e levemente inclinado para trás.","execution":"Conduza os cotovelos para baixo e puxe a barra à frente do rosto até o alto do peito, sem embalar o tronco. Faça uma pausa breve e deixe a barra subir com controle, alongando os braços sem perder o apoio. Na volta acima da cabeça, permita elevação e rotação superior das escápulas. Ao puxar, elas acompanham a descida dos braços; não as mantenha permanentemente presas para baixo.","tips":"Mantenha os punhos alinhados aos antebraços e evite puxar atrás da nuca. Use uma amplitude confortável, sem forçar o contato com o peito. Dorsal, redondo maior e músculos auxiliares participam juntos; cores ilustram participação, sem medir EMG ou intensidade real."}}'::jsonb,"updatedAt"=NOW() WHERE id='00000000-0000-4000-8000-000000000120' AND "ownerUserId" IS NULL AND name='Puxada Frontal' AND "anatomyReview"='{"version":"2026-11-13.1","reviewedAt":"2026-11-13T15:00:00.000Z","variant":"Puxada frontal sentada na polia alta, barra reta e pegada pronada a cerca de 1,5 vez a largura dos ombros; tronco estável levemente reclinado.","aliases":["puxada frontal"],"participants":[{"id":"LATISSIMUS_DORSI","label":"Latíssimo do dorso","muscleGroup":"BACK","role":"PRIMARY","aliases":["dorsal","grande dorsal","latissimus dorsi"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["BUONSENSO_2025","OPENSTAX_UPPER"]},{"id":"TERES_MAJOR","label":"Redondo maior","muscleGroup":"BACK","role":"PRIMARY","aliases":["teres major"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"TRAPEZIUS","label":"Trapézio","muscleGroup":"BACK","role":"SECONDARY","aliases":["trapézio médio","trapézio inferior","trapezius"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["BUONSENSO_2025","OPENSTAX_UPPER"]},{"id":"RHOMBOIDS","label":"Romboides","muscleGroup":"BACK","role":"SECONDARY","aliases":["romboide maior","romboide menor"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"DELTOID_POSTERIOR","label":"Deltoide posterior","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["ombro posterior"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["BUONSENSO_2025","OPENSTAX_UPPER"]},{"id":"INFRASPINATUS","label":"Infraespinal","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["infraespinhoso","manguito rotador"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["BUONSENSO_2025","OPENSTAX_UPPER"]},{"id":"BICEPS_BRACHII","label":"Bíceps braquial","muscleGroup":"BICEPS","role":"SECONDARY","aliases":["bíceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["BUONSENSO_2025","OPENSTAX_UPPER"]},{"id":"BRACHIALIS","label":"Braquial","muscleGroup":"BICEPS","role":"SECONDARY","aliases":["braquial anterior"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"BRACHIORADIALIS","label":"Braquiorradial","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["braquiorradialis"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"FLEXOR_DIGITORUM_SUPERFICIALIS","label":"Flexor superficial dos dedos","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["pegada"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"FLEXOR_DIGITORUM_PROFUNDUS","label":"Flexor profundo dos dedos","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["pegada"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"FLEXOR_CARPI_ULNARIS","label":"Flexor ulnar do carpo","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["punho"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"EXTENSOR_CARPI_RADIALIS_BREVIS","label":"Extensor radial curto do carpo","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["punho"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"ERECTOR_SPINAE","label":"Eretores da coluna","muscleGroup":"BACK","role":"SECONDARY","aliases":["eretor da espinha","estabilizadores do tronco"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"RECTUS_ABDOMINIS","label":"Reto abdominal","muscleGroup":"CORE","role":"SECONDARY","aliases":["abdômen","abdominais"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"EXTERNAL_OBLIQUE","label":"Oblíquo externo","muscleGroup":"CORE","role":"SECONDARY","aliases":["oblíquos"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]}],"sources":[{"id":"BUONSENSO_2025","title":"Buonsenso et al. — Electromyographic Analysis of Back Muscle Activation During Lat Pulldown Exercise (2025)","url":"https://doi.org/10.3390/jfmk10030345","limitation":"40 homens com pelo menos cinco anos de treino; cinco repetições a 70% de 1RM, sete pegadas/inclinações e cadência 2 s/2 s. EMG de dorsal, trapézio médio/inferior, deltoide posterior, bíceps e infraespinal. Sem superioridade geral entre pegadas; maior sinal de deltoide posterior com 30° em comparações específicas. Não mede hipertrofia nem determina ângulos ideais."},{"id":"OPENSTAX_UPPER","title":"OpenStax Anatomy and Physiology 2e — Muscles of the Pectoral Girdle and Upper Limbs","url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/11-5-muscles-of-the-pectoral-girdle-and-upper-limbs","limitation":"Anatomia funcional: adução/extensão do ombro, flexão do cotovelo, controle escapular e pegada. Papéis não medidos no estudo e estabilização do tronco são inferências anatômicas/editoriais, sem quantificação nesta variação."}],"notes":"Dorsal e redondo maior são os motores destacados; flexores do cotovelo, controle escapular, manguito, pegada e estabilizadores do tronco são coenvolvidos. Grupo BACK permanece principal, embora eretores/trapézio/romboides tenham papel secundário específico. Sem isolamento do dorsal, ranking de EMG ou ênfase regional demonstrada. Inclinação fixa de cerca de 7°, barra à frente do rosto e pegada de 1,5 vez os ombros são escolhas ilustrativas confortáveis do rig, não ótimos universais. Não extrapolar os resultados de 30° para esta postura. Sem subdividir dorsal em regiões não comprovadas. Cores representam categorias ilustrativas. Equivalência da execução pronada no pulley verificada no canonical-media-catalog para o UUID ...120; preservado como cadastro distinto, sem fusão de IDs.","instructions":{"description":"Puxada frontal na polia alta, sentada, com barra e pegada pronada moderadamente aberta.","setup":"Ajuste o assento e o apoio sobre as coxas. Apoie os pés no chão e segure a barra um pouco além dos ombros, com as palmas voltadas para a frente. Mantenha o tronco firme e levemente inclinado para trás.","execution":"Conduza os cotovelos para baixo e puxe a barra à frente do rosto até o alto do peito, sem embalar o tronco. Faça uma pausa breve e deixe a barra subir com controle, alongando os braços sem perder o apoio.","tips":"Mantenha os punhos alinhados aos antebraços e evite puxar atrás da nuca. Use uma amplitude confortável, sem forçar o contato com o peito. Dorsal, redondo maior e músculos auxiliares participam juntos; cores ilustram participação, sem medir EMG ou intensidade real."}}'::jsonb AND (SELECT string_agg(m.role::text || ':' || m."muscleGroup"::text,'|' ORDER BY m.role::text || ':' || m."muscleGroup"::text) FROM "ExerciseMuscle" m WHERE m."exerciseId"="Exercise".id)='PRIMARY:BACK|SECONDARY:BICEPS|SECONDARY:CORE|SECONDARY:FOREARMS|SECONDARY:SHOULDERS';
COMMIT;
